fn c_read(s: *const c_char) -> Vec<u8> {
    // SAFETY: the callers pass a live NUL-terminated string.
    let len = unsafe { libc::strlen(s) };
    // SAFETY: `len` bytes precede the NUL.
    unsafe { std::slice::from_raw_parts(s.cast::<u8>(), len) }.to_vec()
